const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    var line = ee.Geometry.LineString([[-90.09, 35.15], [-90.05, 35.15]]);
    var bufferMeters = 800; // each side
    var roi = line.buffer(bufferMeters);
    var lineLen = line.length(); // meters

    var scale = 1000; // per instruction to avoid timeout
    var maxPixels = 1e9;
    var periods = [
      {label: '2021-09', start: '2021-09-01', end: '2021-10-01'},
      {label: '2023-09', start: '2023-09-01', end: '2023-10-01'}
    ];

    function maskS2(img) {
      var qa = img.select('QA60');
      var cloudBitMask = 1 << 10;
      var cirrusBitMask = 1 << 11;
      var mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(qa.bitwiseAnd(cirrusBitMask).eq(0));
      return img.updateMask(mask).divide(10000)
        .select(['B3','B8','B11'], ['green','nir','swir1']);
    }

    function getS2Composite(start, end) {
      var col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterDate(start, end)
        .filterBounds(roi)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80))
        .map(maskS2);
      return {col: col, size: col.size()};
    }

    function maskL8L9(img) {
      var qa = img.select('QA_PIXEL');
      var mask = qa.bitwiseAnd(1 << 1).eq(0) // dilated cloud
        .and(qa.bitwiseAnd(1 << 2).eq(0))    // cirrus
        .and(qa.bitwiseAnd(1 << 3).eq(0))    // cloud
        .and(qa.bitwiseAnd(1 << 4).eq(0));   // cloud shadow
      var scaled = img.updateMask(mask)
        .select(['SR_B3','SR_B5','SR_B6'], ['green','nir','swir1'])
        .multiply(0.0000275).add(-0.2);
      return scaled;
    }

    function getLandsatComposite(start, end) {
      var l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterDate(start, end).filterBounds(roi).map(maskL8L9);
      var l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2').filterDate(start, end).filterBounds(roi).map(maskL8L9);
      var col = l8.merge(l9);
      return {col: col, size: col.size()};
    }

    function compositeFromCollections(start, end) {
      var s2 = getS2Composite(start, end);
      var s2Size = s2.size.getInfo();
      if (s2Size > 0) {
        return {img: s2.col.median(), source: 'S2', n: s2Size};
      }
      var ls = getLandsatComposite(start, end);
      var lsSize = ls.size.getInfo();
      if (lsSize > 0) {
        return {img: ls.col.median(), source: 'Landsat', n: lsSize};
      }
      return {img: null, source: 'None', n: 0};
    }

    function metricsForImage(img) {
      var mndwi = img.expression('(G - S)/(G + S)', {'G': img.select('green'), 'S': img.select('swir1')}).rename('mndwi');
      var waterMask = mndwi.gt(0);
      var totalPix = ee.Image.constant(1).rename('const')
        .reduceRegion({reducer: ee.Reducer.count(), geometry: roi, scale: scale, maxPixels: maxPixels})
        .get('const');
      var validPix = img.select('green')
        .reduceRegion({reducer: ee.Reducer.count(), geometry: roi, scale: scale, maxPixels: maxPixels})
        .get('green');
      var waterPix = ee.Image.constant(1).rename('const').updateMask(waterMask)
        .reduceRegion({reducer: ee.Reducer.count(), geometry: roi, scale: scale, maxPixels: maxPixels})
        .get('const');
      var waterArea = ee.Image.pixelArea().rename('area').updateMask(waterMask)
        .reduceRegion({reducer: ee.Reducer.sum(), geometry: roi, scale: scale, maxPixels: maxPixels})
        .get('area');
      return {
        totalPix: ee.Number(totalPix),
        validPix: ee.Number(validPix),
        waterPix: ee.Number(waterPix),
        waterArea: ee.Number(waterArea)
      };
    }

    console.log(`Transect length (m): ${lineLen.getInfo().toFixed(0)}, Buffer (m): ${bufferMeters}`);

    var results = [];
    var anyEmpty = false;
    var anyNoValid = false;

    for (var i = 0; i < periods.length; i++) {
      var p = periods[i];
      var comp = compositeFromCollections(p.start, p.end);
      if (comp.n === 0 || comp.img === null) {
        console.log(`${p.label} Images: 0`);
        anyEmpty = true;
        results.push({label: p.label, source: 'None', n: 0, validPix: 0, totalPix: 0, waterPix: 0, width: null});
        continue;
      }
      var met = metricsForImage(comp.img);
      var totalPix = met.totalPix.getInfo();
      var validPix = met.validPix.getInfo();
      var waterPix = met.waterPix.getInfo();
      var waterArea = met.waterArea.getInfo(); // m2
      if (totalPix === null || validPix === null || (totalPix|0) === 0) {
        console.log(`${p.label} Images: ${comp.n} (${comp.source}), totalPix invalid`);
        anyNoValid = true;
        results.push({label: p.label, source: comp.source, n: comp.n, validPix: 0, totalPix: totalPix || 0, waterPix: 0, width: null});
        continue;
      }
      if ((validPix|0) === 0) {
        console.log(`${p.label} Images: ${comp.n} (${comp.source}), ValidPix: 0/${totalPix}`);
        anyNoValid = true;
        results.push({label: p.label, source: comp.source, n: comp.n, validPix: 0, totalPix: totalPix, waterPix: 0, width: null});
        continue;
      }
      var width = null;
      if (waterArea !== null && isFinite(waterArea)) {
        var len = lineLen.getInfo();
        width = waterArea / len;
      }
      var cloudPct = totalPix > 0 ? (1 - validPix / totalPix) * 100 : null;
      console.log(`${p.label} Images: ${comp.n} (${comp.source}), Valid/Total: ${validPix}/${totalPix} (~Cloud ${cloudPct !== null ? cloudPct.toFixed(1) : 'NA'}%), WaterPix: ${waterPix}, WaterArea(m2): ${waterArea !== null ? waterArea.toFixed(0) : 'NA'}, EstWidth(m): ${width !== null ? width.toFixed(1) : 'NA'}`);
      results.push({label: p.label, source: comp.source, n: comp.n, validPix: validPix, totalPix: totalPix, waterPix: waterPix, width: width});
    }

    if (anyEmpty) {
      console.log('C1');
      return;
    }
    if (anyNoValid) {
      console.log('C2');
      return;
    }

    var w2021 = results[0].width;
    var w2023 = results[1].width;
    if (w2021 === null || w2023 === null || !isFinite(w2021) || !isFinite(w2023) || w2021 < 0 || w2023 < 0) {
      console.log('C3');
      return;
    }
    var d = w2023 - w2021;
    console.log(`Change (2023 - 2021) width (m): ${d.toFixed(1)}`);
    if (w2023 < w2021) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
